let db,transactions=[],budgets=[],goals=[],accounts=[],selectedView='overview',chartRange=6,toastTimer,sourceForNext='manual',quickExpenseCategory='Food',quickCategoryTouched=false,quickExpenseSaving=false,quickUndoTimer=0,lastQuickSavedId='',hapticEnabled=false,pendingVoiceTarget='entry';
